import jwt from 'jsonwebtoken';
import Stripe from 'stripe';

export default async function stripeGetSubscription(
  { sessionToken, sessionSecret, stripeSecretKey },
  { logging, http }
) {
  // 1. Verify session JWT
  if (!sessionToken || typeof sessionToken !== 'string' || sessionToken.trim() === '') {
    http?.status(401);
    return { error: 'Unauthorized' };
  }

  if (!sessionSecret) {
    logging.log('Missing SESSION_SECRET configuration');
    http?.status(500);
    return { error: 'Server configuration error' };
  }

  let claims;
  try {
    claims = jwt.verify(sessionToken.trim(), sessionSecret, { algorithms: ['HS256'] });
  } catch (err) {
    logging.log('Session JWT verification failed:', err.name, err.message);
    http?.status(401);
    return { error: 'Unauthorized' };
  }

  const email = claims?.email;
  if (!email || typeof email !== 'string' || !email.includes('@')) {
    logging.log('Session JWT missing valid email claim');
    http?.status(401);
    return { error: 'Unauthorized' };
  }

  logging.log('Session verified for:', email);

  if (!stripeSecretKey) {
    logging.log('Missing STRIPE_SECRET_KEY configuration');
    http?.status(500);
    return { error: 'Server configuration error' };
  }

  const stripe = new Stripe(stripeSecretKey, { apiVersion: '2023-10-16' });

  // 2. Look up Stripe customer by email
  let customer;
  try {
    const result = await stripe.customers.list({ email, limit: 1 });
    customer = result.data[0] ?? null;
  } catch (err) {
    logging.log('Stripe customer lookup failed:', err.message);
    http?.status(502);
    return { error: 'Failed to retrieve subscription data' };
  }

  // No customer record — definitely on free tier
  if (!customer) {
    logging.log('No Stripe customer found for:', email);
    return { tier: 'free', status: 'none' };
  }

  logging.log('Found Stripe customer:', customer.id);

  // 3. Read metadata set by webhook handler
  const metadata = customer.metadata || {};
  const tier           = metadata.ccc_tier           || 'free';
  const status         = metadata.ccc_status         || 'none';
  const subscriptionId = metadata.ccc_subscription_id || null;

  // 4. Fetch current_period_end from live subscription if ID exists
  let periodEnd = undefined;
  if (subscriptionId) {
    try {
      const subscription = await stripe.subscriptions.retrieve(subscriptionId);
      if (subscription?.current_period_end) {
        // Convert Unix timestamp to YYYY-MM-DD
        periodEnd = new Date(subscription.current_period_end * 1000)
          .toISOString()
          .split('T')[0];
      }
      logging.log('Subscription period end:', periodEnd);
    } catch (err) {
      // Non-fatal — metadata is the source of truth for tier/status
      logging.log('Could not retrieve subscription details:', err.message);
    }
  }

  // 5. Return
  const result = { tier, status };
  if (periodEnd) result.periodEnd = periodEnd;

  logging.log('Returning subscription:', result);
  return result;
}

